INSERT INTO DiaryEntries (EntryDate, Title, Content) VALUES
('2026-01-05 08:12:00', 'Uusi vuosi', 'Aloitin vuoden hyvillä fiiliksillä. Teimme perheen kanssa aamupalaa ja suunnittelimme vuoden tavoitteita.'),
('2026-01-12 19:40:00', 'Lumisade', 'Ulkona satoi lunta koko päivän. Rakensin pihalle lumiukon naapurin lasten kanssa.'),
('2026-01-28 13:05:00', 'Treenipäivä', 'Kävin salilla ensimmäistä kertaa pitkään aikaan. Lihakset ovat varmasti kipeät huomenna.'),
('2026-02-03 09:30:00', 'Flunssa iskee', 'Heräsin kuumeisena. Vietin päivän sängyssä teetä juoden.'),
('2026-02-14 20:00:00', 'Ystävänpäivä', 'Vietimme iltaa ystävien kanssa pelaten lautapelejä. Naurua riitti.'),
('2026-02-22 11:15:00', 'Hiihtoloma alkaa', 'Pakkasin laukut ja lähdimme mökille viikoksi. Innolla odotan rinteitä.'),
('2026-03-01 07:45:00', 'Takaisin arkeen', 'Loma loppui liian nopeasti. Palasin töihin väsyneenä mutta hyvillä muistoilla.'),
('2026-03-10 15:50:00', 'Kevät tulossa', 'Huomasin ensimmäiset krokukset pihalla. Aurinko lämmittää jo mukavasti.'),
('2026-03-19 18:20:00', 'Elokuvailta', 'Katsoimme uuden scifi-elokuvan ystävän kanssa. Juoni yllätti täysin.'),
('2026-04-02 10:10:00', 'Siivouspäivä', 'Siivosin koko asunnon kevätkuntoon. Löysin kaapista vanhoja valokuvia.'),
('2026-04-15 21:05:00', 'Myöhäinen kirjoitusilta', 'En saanut unta, joten päätin kirjoittaa pitkästä aikaa päiväkirjaa.'),
('2026-04-27 08:00:00', 'Pyöräretki', 'Pyöräilin ensimmäistä kertaa tänä keväänä. Ilma oli raikas ja mieli kirkas.'),
('2026-05-05 17:35:00', 'Ruoanlaittoa', 'Kokeilin uutta reseptiä, thaimaalaista currya. Lopputulos oli yllättävän hyvä.'),
('2026-05-18 12:40:00', 'Puutarhatyöt', 'Istutin tomaatteja ja yrttejä parvekkeelle. Toivottavasti ne kasvavat hyvin.'),
('2026-06-01 09:25:00', 'Kesä alkaa', 'Viimeinen työpäivä ennen kesälomaa. Fiilis on huikea.'),
('2026-06-12 22:50:00', 'Juhannuksen valmistelua', 'Ostimme ruokaa mökkiviikonloppua varten. Sää näyttää lupaavalta.'),
('2026-06-21 23:30:00', 'Juhannusyö', 'Vietimme juhannusta mökillä. Saunoimme ja katsoimme auringonlaskua pitkään.'),
('2026-07-04 14:00:00', 'Uimaranta', 'Kävimme perheen kanssa uimarannalla. Vesi oli juuri sopivan lämmintä.'),
('2026-07-19 10:15:00', 'Marjastusta', 'Poimimme mustikoita metsässä. Sormet värjäytyivät siniseksi.'),
('2026-08-02 16:45:00', 'Festivaalipäivä', 'Kävin musiikkifestivaalilla ystävien kanssa. Keikat olivat mahtavia.'),
('2026-08-15 07:55:00', 'Koulut alkavat pian', 'Valmistelin opiskelutarvikkeita syksyä varten. Uusi lukuvuosi lähestyy.'),
('2026-08-29 19:20:00', 'Sieniretki', 'Löysimme metsästä kantarelleja. Illalla paistoimme niitä voissa.'),
